from typing import List

def minSum(nums1: List[int], nums2: List[int]) -> int:
    """
    Calculates the minimum possible equal sum of two arrays by replacing 0s 
    with strictly positive integers (>= 1).

    Args:
        nums1: A list of non-negative integers.
        nums2: A list of non-negative integers.

    Returns:
        The minimum possible equal sum, or -1 if it's impossible to achieve.
    """
    # Calculate the current sum (excluding zeros) and count of zeros for both arrays
    sum1 = 0
    count1 = 0
    for x in nums1:
        if x == 0:
            count1 += 1
        else:
            sum1 += x

    sum2 = 0
    count2 = 0
    for x in nums2:
        if x == 0:
            count2 += 1
        else:
            sum2 += x

    # The minimum sum we can reach for each array is its current sum + the number of zeros,
    # because each zero must be replaced by at least a 1.
    min_total1 = sum1 + count1
    min_total2 = sum2 + count2

    # Case 1: Both arrays have zeros to fill.
    # We can make both sums equal to any value X such that X >= min_total1 and X >= min_total2.
    # The minimum such integer is the maximum of the two minimum totals.
    if count1 > 0 and count2 > 0:
        return max(min_total1, min_total2)

    # Case 2: Only nums1 has zeros to fill.
    # The sum of nums2 is fixed (since it contains no zeros).
    # We need the fixed sum2 to be at least the minimum possible sum of nums1.
    elif count1 > 0 and count2 == 0:
        if sum2 >= min_total1:
            return sum2
        else:
            return -1

    # Case 3: Only nums2 has zeros to fill.
    # The sum of nums1 is fixed (since it contains no zeros).
    # We need the fixed sum1 to be at least the minimum possible sum of nums2.
    elif count1 == 0 and count2 > 0:
        if sum1 >= min_total2:
            return sum1
        else:
            return -1

    # Case 4: Neither array has zeros.
    # The sums must already be equal.
    else:
        if sum1 == sum2:
            return sum1
        else:
            return -1

