def longestSemiRepetitiveSubstring(s: str) -> int:
    max_len = 0
    n = len(s)

    # 使用雙層迴圈檢查所有可能的子字串
    for i in range(n):
        repeat_count = 0
        for j in range(i + 1, n):
            # 如果當前字元與前一個字元相同，計數加 1
            if s[j] == s[j-1]:
                repeat_count += 1

            # 如果連續重複次數超過 1，則不符合 semi-repetitive 定義
            if repeat_count <= 1:
                max_len = max(max_len, j - i + 1)
            else:
                # 一旦超過 1 次重複，擴展更長的子字串也一定不符合條件，可直接跳出內層迴圈
                break

    return max_len
