from typing import List

def longestCommonPrefix(arr1: List[int], arr2: List[int]) -> int:
    # A Trie will store all prefixes of integers in arr1
    # Since the maximum value is 10^8, each integer has at most 9 digits.
    trie = {}
    for x in arr1:
        s = str(x)
        curr = trie
        for char in s:
            if char not in curr:
                curr[char] = {}
            curr = curr[char]

    max_len = 0
    # For each integer y in arr2, find the longest prefix that exists in our Trie.
    # The maximum such length across all y is the answer.
    for y in arr2:
        s = str(y)
        curr = trie
        depth = 0
        for char in s:
            if char in curr:
                depth += 1
                curr = curr[char]
            else:
                break
        if depth > max_len:
            max_len = depth

    return max_len

