def findPrimePairs(n: int):
    if n < 4:
        return []

    # 使用篩法 (Sieve of Eratosthenes) 預處理所有質數
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False

    result = []
    # 遍歷 x，條件為 x <= y 且 x + y == n，故 x 最多到 n // 2
    for x in range(2, (n // 2) + 1):
        y = n - x
        if is_prime[x] and is_prime[y]:
            result.append([x, y])

    return result
