def findPrimePairs(n: int):
    if n < 4:
        return []

    # Sieve of Eratosthenes to precompute primes up to n
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p*p, n + 1, p):
                is_prime[i] = False

    res = []
    # Since x <= y and x + y == n, it follows that 2x <= n, so x <= n/2.
    # We iterate through all possible values of x starting from the smallest prime (2).
    for x in range(2, (n // 2) + 1):
        y = n - x
        if is_prime[x] and is_prime[y]:
            res.append([x, y])

    return res

