import collections

def minimumOperationsToMakeEqual(x: int, y: int):
    # 使用廣度優先搜尋 (BFS) 來尋找最短路徑（最少操作次數）
    if x == y:
        return 0

    # queue 儲存 (當前數值, 操作次數)
    queue = collections.deque([(x, 0)])
    # visited 用於記錄已經訪問過的數字，避免重複計算與無限迴圈
    visited = {x}

    while queue:
        curr, dist = queue.popleft()

        if curr == y:
            return dist

        # 產生所有可能的下一步操作
        next_steps = []
        if curr % 11 == 0:
            next_steps.append(curr // 11)
        if curr % 5 == 0:
            next_steps.append(curr // 5)
        next_steps.append(curr + 1)
        next_steps.append(curr - 1)

        for next_val in next_steps:
            # 設定合理的邊界：數值必須大於 0，且為了效能考慮，
            # 限制在一個較大的範圍內（例如 20000，因為 x, y 最大為 10^4）
            if 0 < next_val <= 20000 and next_val not in visited:
                visited.add(next_val)
                queue.append((next_val, dist + 1))

    return -1
