from collections import deque

def minimumOperationsToMakeEqual(x: int, y: int):
    # BFS to find the shortest path in an unweighted graph
    queue = deque([(x, 0)])
    visited = {x}

    while queue:
        curr_x, steps = queue.popleft()

        if curr_x == y:
            return steps

        # Possible next states
        next_states = []
        if curr_x % 11 == 0:
            next_states.append(curr_x // 11)
        if curr_x % 5 == 0:
            next_states.append(curr_x // 5)
        next_states.append(curr_x + 1)
        next_states.append(curr_x - 1)

        for next_val in next_states:
            # Constraints: x, y are positive integers (>= 1).
            # We set a reasonable upper bound to prevent infinite search.
            if 0 <= next_val <= 20000 and next_val not in visited:
                visited.add(next_val)
                queue.append((next_val, steps + 1))
