def removeAlmostEqualCharacters(word: str):
    # dp[c] stores the minimum operations to satisfy conditions for the prefix processed so far,
    # where the last character placed was c (0-25 representing 'a'-'z').
    dp = [1 if i != ord(word[0]) - 97 else 0 for i in range(26)]

    for i in range(1, len(word)):
        new_dp = [float('inf')] * 26
        target = ord(word[i]) - 97
        # Try every possible character for the current position
        for curr_c in range(26):
            cost = 0 if curr_c == target else 1
            # Check against every possible preceding character
            for prev_c in range(26):
                if abs(curr_c - prev_c) > 1:
                    if dp[prev_c] + cost < new_dp[curr_c]:
                        new_dp[curr_c] = dp[prev_c] + cost
        dp = new_dp

    return min(dp)

